    public class Database
    {
        public List<Enfant> Enfants { get; set; }
        public List<Parent> Parents { get; set; }
        public List<Favoris> Favori { get; set; }


        public Database()
        {
            Parents = new List<Parent>();
            Enfants = new List<Enfant>();
            Favori = new List<Favoris>();
            


            Parents.Add(new Parent() { Id = 1, Nom = "Support", ImageParent = "Images/sens.jfif", Description = "Les opérateurs de support fournissent à leurs coéquipiers une protection physique ou des utilitaires supplémentaires pour atteindre les objectifs.\r\nDroner pour l’équipe et repérer les ennemis.\r\nPoser des gadgets utilitaires (ex: Caméra, Donner du soin)." });
            Parents.Add(new Parent() { Id = 2, Nom = "Anti-Gadget", ImageParent = "Images/Impact_EMP_Grenade.webp", Description = "Les opérateurs anti-gadgets augmentent la vulnérabilité des adversaires et défendent leurs coéquipiers en détruisant ou en désactivant les gadgets des adversaires.\r\nDétruire les gadgets défensifs (brouilleurs, batteries, pièges).\r\nDésactiver les systèmes de surveillance adverses.\r\nEmpêcher les défenseurs de ralentir l’attaque." });
            Parents.Add(new Parent() { Id = 3, Nom = "Breacher", ImageParent = "Images/téléchargement.jpg", Description = "Les opérateurs de brèche créent des entrées et des lignes de vue sur des surfaces cassables ou renforcées pour exposer les adversaires et aider leurs coéquipiers à atteindre leurs objectifs.\r\nOuvrir les murs et trappes renforcés.\r\nCréer des angles d’attaque avantageux." });

            Enfants.Add(new Enfant() { Id = 1, IdParent = 1, Nom = "Valkyrie", Âge = "31 ans", ImageEnfant = "Images/téléchargement.jfif", Camp = "Défenseur", Clan = "SEAL", NiveauDeDifficultés = 2, Abilité = "Black eye",Fonction = "Support", Description = "Valkyrie est une opératrice de la défense, issue du FBI. Elle est connue pour son expertise en espionnage et ses compétences tactiques. Voici une description de son personnage et de son rôle dans le jeu :Valkyrie possède une apparence déterminée et pragmatique, avec un équipement qui reflète son rôle de spécialiste dans la collecte d'informations. Elle est souvent représentée avec un équipement tactique et une attitude confiante.\r\n\r\nCapacité (ou Gadget) :\r\nBlack Eye : Valkyrie est équipée de caméras de surveillance spéciales, appelées \"Black Eyes\". Elle peut placer ces caméras à différents endroits sur la carte, ce qui permet de surveiller les mouvements des attaquants et de fournir des informations cruciales à son équipe. Les Black Eyes sont discrètes et peuvent être placées sur des surfaces variées, offrant ainsi des angles de vue uniques et imprévisibles. De plus, Valkyrie peut voir à travers ces caméras à tout moment et peut également les activer pour les utiliser comme des caméras de surveillance en temps réel.\r\nLa combinaison de sa capacité à placer des caméras et son armement solide en fait une opératrice très appréciée et stratégique, capable d'influencer le cours des attaques ennemies grâce à une vision accrue du terrain." });
            Enfants.Add(new Enfant() { Id = 2, IdParent = 1, Nom = "Doc", Âge = "39 ans", ImageEnfant = "Images/Doc.jfif", Camp = "Défenseur", Clan = "GIGN", NiveauDeDifficultés = 1, Abilité = "Stim Pistol", Fonction = "Support", Description = "Doc est un agent de l'unité GIGN dans le jeu Rainbow Six Siege. Il est classé comme un défenseur et est connu pour son rôle de soutien en équipe grâce à sa capacité unique. Son gadget principal est le \"Stim Pistol\", qui lui permet de tirer des seringues de stimulation à ses coéquipiers. Voici une description de ses caractéristiques et de son habilité :Capacité :\r\nStim Pistol : Doc peut utiliser son pistolet à seringues pour administrer des stimulants à ses coéquipiers. Cela leur permet de récupérer des points de vie, mais aussi de les ramener à la vie s'ils sont dans un état d'errance. Cela fait de Doc un agent crucial pour maintenir son équipe en vie lors des affrontements.\r\nCette capacité de soutien lui permet de renforcer la résilience de son équipe tout en offrant une certaine flexibilité tactique pendant les opérations. Grâce à son arme et son gadget, Doc peut occuper un rôle central dans la dynamique de jeu de l’équipe.Capacité :\r\nStim Pistol : Doc peut utiliser son pistolet à seringues pour administrer des stimulants à ses coéquipiers. Cela leur permet de récupérer des points de vie, mais aussi de les ramener à la vie s'ils sont dans un état d'errance. Cela fait de Doc un agent crucial pour maintenir son équipe en vie lors des affrontements.\r\nCette capacité de soutien lui permet de renforcer la résilience de son équipe tout en offrant une certaine flexibilité tactique pendant les opérations. Grâce à son arme et son gadget, Doc peut occuper un rôle central dans la dynamique de jeu de l’équipe." });
            Enfants.Add(new Enfant() { Id = 3, IdParent = 1, Nom = "Mira", Âge = "39 ans", ImageEnfant = "Images/Mira.jfif", Camp = "Défenseur", Clan = "SEAL", NiveauDeDifficultés = 3, Abilité = "Black Mirror", Fonction = "Support", Description = "Mira est un opérateur défensif qui fait partie de l'unité espagnole de la Gendarmerie. Elle est connue pour sa capacité à renforcer la défense des objectifs grâce à des gadgets uniques.Mira est présentée comme une opératrice tactique avec une expertise en ingénierie et en sécurité. Elle est caractérisée par son intelligence et sa capacité à analyser rapidement les situations. Son style est moderne et fonctionnel, ce qui reflète son sérieux et son efficacité sur le terrain.\r\n\r\nCapacité :\r\nL'abilité unique de Mira est le \"Black Mirror\". Il s'agit d'un dispositif qui crée une fenêtre renforcée permettant aux défenseurs de voir à travers tout en étant protégés derrière un verre blindé. Cet outil permet aux joueurs de surveiller les angles et de tenir des points stratégiques tout en restant cachés. \r\n\r\nCaractéristiques du Black Mirror :\r\nLa fenêtre est indestructible par balles et peut être placée sur des murs renforcés.\r\nElle peut être activée pour laisser passer la lumière et permettre aux défenseurs de tirer à travers, tout en offrant une vision à travers la vitre.\r\nLes attaquants peuvent détruire le Black Mirror avec des explosifs ou des coups de melee au niveau de la vitre, mais cela nécessite une certaine stratégie de leur part.\r\nEn résumé, Mira est une opératrice qui renforce les défenses d'une manière unique, offrant des opportunités de vision et de tir tout en protégeant les défenseurs." });

            Enfants.Add(new Enfant() { Id = 4, IdParent = 2, Nom = "Jager", Âge = "38 ans", ImageEnfant = "Images/Jager.jfif", Camp = "Défenseur", Clan = "GSG 9", NiveauDeDifficultés = 2, Abilité = "ADS", Fonction = "Anti-Gadget", Description = "Jäger est un opérateur défensif de Rainbow Six Siege. Expert en lutte contre les explosifs, il utilise son système ADS pour intercepter les projectiles ennemis. \r\n                        Grâce à cette capacité, il est indispensable pour protéger des points stratégiques contre les assauts ennemis.\r\n                        C'est un membre clé du GSG 9 et il est apprécié pour sa polyvalence en défense.Jäger est équipé de trois dispositifs Magpie, \r\n                        des systèmes de défense anti-projectiles qui interceptent et détruisent automatiquement les grenades, les charges explosives,\r\n                         les grenades fumigènes et autres projectiles lancés par les attaquants. Chaque Magpie peut neutraliser deux projectiles avant d'être désactivé. \r\n                         Ce gadget est essentiel pour protéger les zones stratégiques, comme les sites de bombe, \r\n                         et pour contrer les opérateurs offensifs qui comptent sur des explosifs pour ouvrir des brèches ou déloger les défenseurs. Jäger est un opérateur incontournable pour toute équipe défensive dans Rainbow Six Siege. \r\n                         Son gadget unique, combiné à son arsenal puissant, en fait un choix stratégique pour contrer les attaquants et sécuriser les zones clés. \r\n                         Que vous soyez un joueur expérimenté ou un débutant, Jäger offre une polyvalence et une utilité qui peuvent faire la différence entre la victoire et la défaite." });
            Enfants.Add(new Enfant() { Id = 5, IdParent = 2, Nom = "Thatcher", Âge = "56 ans", ImageEnfant = "Images/thatcher.jpg", Camp = "Attaquant", Clan = "SAS", NiveauDeDifficultés = 1, Abilité = "EMP Grenade", Fonction = "Anti-Gadget", Description = "Thatcher est un opérateur d'attaque emblématique du SAS (Special Air Service, une unité spéciale britannique).Fonctionnement :\r\nThatcher lance une grenade électromagnétique (EMP) qui désactive temporairement ou détruit les dispositifs électroniques dans sa zone d'effet.\r\n\r\nEffets :\r\n\r\nDésactive les gadgets électroniques ennemis (ex: pièges Kapkan, dispositifs d'interception Mute, batteries électriques Bandit, etc.)\r\n\r\nPeut rendre inactives les caméras, les dispositifs de défense automatiques et autres équipements électroniques.\r\n\r\nMécanique récente :\r\nDepuis une mise à jour, au lieu de détruire directement tous les gadgets, les EMP de Thatcher désactivent la plupart des appareils pendant quelques secondes, laissant le temps à son équipe d’agir (comme ouvrir un mur électrifié)." });
            Enfants.Add(new Enfant() { Id = 6, IdParent = 2, Nom = "Mute", Âge = "25 ans", ImageEnfant = "Images/Mute.jpg", Camp = "Défenseur", Clan = "SAS", NiveauDeDifficultés = 1, Abilité = "Signal Disuptor", Fonction = "Anti-Gadget", Description = "Mute est un opérateur défenseur lui aussi issu du SAS (comme Thatcher).Son gadget spécial : brouilleur de signaux (Signal Disruptor - « Jammer »)\r\nFonctionnement :\r\nMute peut poser des petits brouilleurs au sol qui créent un champ électromagnétique.\r\nTout appareil électronique ennemi entrant dans ce champ est soit bloqué, soit empêché de fonctionner.\r\n\r\nEffets :\r\n\r\nBloque les drones ennemis (empêche la reconnaissance pendant la phase de préparation et durant le round).\r\n\r\nEmpêche les charges du type Thermite, Hibana, ou Ace d'exploser ou de fonctionner correctement.\r\n\r\nPeut bloquer les gadgets comme les grenades téléguidées, les claymores, les caméras ennemies, etc.\r\n\r\nMécanique récente :\r\nSes brouilleurs ont une zone d'effet circulaire (et peuvent être visibles par certains gadgets spéciaux comme ceux de IQ).\r\nS'ils sont détruits ou désactivés par une IEM (comme celle de Thatcher), les appareils qu'ils bloquaient peuvent fonctionner de nouveau." });
            Enfants.Add(new Enfant() { Id = 7, IdParent = 2, Nom = "Bandit", Âge = "42 ans", ImageEnfant = "Images/bandit.jpg", Camp = "Défenseur", Clan = "GSG 9", NiveauDeDifficultés = 1, Abilité = "Shock Wire", Fonction = "Anti-Gadget", Description = "Bandit est un opérateur défensif dans le jeu Rainbow Six Siege, issu de l'unité GSG 9 allemande. Il est souvent associé à un style de jeu axé sur la rapidité et la surprise.Capacité :\r\nL'abilité de Bandit est appelée \"Shock Wire\". Cette capacité lui permet d'utiliser un dispositif que l'on place sur les électroménagers, tels que les murs renforcés en métal. Voici quelques caractéristiques de l'abilité :\r\n\r\nFonctionnement : Bandit peut électrifier les murs renforcés en utilisant ses fils électriques. Cela empêche les ennemis de détruire les murs renforcés avec des explosifs (comme des charges de thermite) tant que la capacité est active.\r\nDégâts : Les ennemis qui tentent de détruire ou de passer à travers ces murs électrifiés subissent des dégâts, ce qui peut les désavantager lors de l'assaut.\r\nUtilisation stratégique : Bandit est souvent utilisé pour déjouer les tentatives de pénétration par des opérateurs comme Thermite ou Hibana, en les forçant à réfléchir à deux fois avant de détruire les murs.\r\nLe jeu de Bandit repose donc sur une bonne connaissance des timings et des emplacements des murs renforcés pour maximiser son impact pendant les rounds." });
            Enfants.Add(new Enfant() { Id = 8, IdParent = 2, Nom = "Vigil", Âge = "34 ans", ImageEnfant = "Images/vigil.jpg", Camp = "Défenseur", Clan = "South Korean Navy , 707e unité de contre-terrorisme. ", NiveauDeDifficultés = 3, Abilité = "ERC-7", Fonction = "Anti-Gadget", Description = "Vigil est un opérateur défensif dans le jeu \"Rainbow Six Siege\". Il est originaire de la Corée du Sud et fait partie de l'unité d'élite de la police spéciale, la 707e unité de contre-terrorisme.Vigil est un opérateur qui se spécialise dans la dissimulation et le camouflage. Son rôle principal est de perturber les attaques des attaquants en restant invisible sur leur radar. Bien qu'il ne soit pas aussi robuste que certains autres opérateurs défensifs, sa capacité à éviter la détection en fait un atout précieux pour l'équipe.Capacité\r\nL'aptitude unique de Vigil est le \"ECM (Electronic Cloaking Mask)\". Voici comment cela fonctionne :\r\n\r\nECM : Vigil utilise un dispositif qui brouille les drones ennemis et rend difficile leur détection. Quand il se déplace tout en utilisant ce dispositif, il devient invisible aux drones adverses, et son détecteur ne l'identifiera pas. Cela lui permet de localiser des attaquants tout en étant difficile à détecter.\r\nEffet : En utilisant cette capacité, Vigil peut se faufiler derrière les attaquants et surprendre ceux qui s'approchent, tout en permettant à son équipe de se défendre plus efficacement.\r\nCette capacité de dissimulation, combinée à son armement solide, fait de Vigil un opérateur redoutable pour tourmenter les attaquants et les forcer à être plus prudents dans leur approche. \r\n\r\nDans l'ensemble, Vigil est un opérateur qui joue sur la stratégie et la psychologique, rendant les joueurs hésitants et méfiants face à ses mouvements." });

            Enfants.Add(new Enfant() { Id = 9, IdParent = 3, Nom = "Maverick", Âge = "36 ans", ImageEnfant = "Images/maverick.jpg", Camp = "Attaquant", Clan = "U.S Army", NiveauDeDifficultés = 2, Abilité = "Breaching Torch", Fonction = "Breacher", Description = "Maverick est un opérateur attaquant dans le jeu \"Rainbow Six Siege\". Il fait partie de l'unité des États-Unis, le FBI SWAT, et est introduit avec l'extension \"Operation Grim Sky\".\r\n\r\nDescription :\r\nMaverick est décrit comme un opérateur ingéniosité, capable de s'adapter à diverses situations sur le champ de bataille. Il est un spécialiste des interventions tactiques, capable de prendre des décisions rapides et efficaces pour déjouer les pièges ennemis et ouvrir de nouvelles voies pour son équipe.\r\n\r\nCapacité :\r\nL'arme spéciale de Maverick est le \"Blowtorch\" (ou \"Tueur de flammes)\". Cet outil lui permet de créer des trous dans des murs renforcés, des barbelés et d'autres surfaces destructibles en utilisant une flamme à basse intensité. Contrairement à d'autres opérateurs qui doivent utiliser des explosifs ou des charges breaching, le Blowtorch offre à Maverick une méthode silencieuse et discrète pour pénétrer les défenses ennemies. Cela lui permet de créer des angles de tir sans alerter immédiatement l'ennemi et de surprendre les défenseurs.\r\n\r\nEn résumé, Maverick est un opérateur polyvalent qui excelle dans l'ouverture de nouvelles voies pour son équipe tout en restant discret et tactique." });
            Enfants.Add(new Enfant() { Id = 10, IdParent = 3, Nom = "Thermite", Âge = "35 ans", ImageEnfant = "Images/thermite.jpg", Camp = "Attaquant", Clan = "FBI SWAT", NiveauDeDifficultés = 1, Abilité = "Exothermic Charge", Fonction = "Breacher", Description = "Thermite est un attaquant d'origine américaine. Il est reconnu pour sa capacité à détruire des murs renforcés, ce qui en fait un personnage clé lors des phases d'attaque. \r\n\r\n Description :\r\nThermite est un ancien membre des forces spéciales des États-Unis qui a été recruté par le FBI. Il est un expert en explosifs et en démolition, misant sur son savoir-faire technique pour mener à bien les opérations. Sa personnalité reflète une approche méthodique et réfléchie, et il est souvent perçu comme un leader naturel sur le terrain.\r\n\r\nCapacité :\r\nL’aptitude principale de Thermite est le \"Breaching Charge\", souvent appelé \"Exothermic Charge\". Cette capacité lui permet de poser une charge explosive sur les murs renforcés (ou certaines surfaces renforcées), créant un passage large et sécurisé pour son équipe. Lorsqu'elle est activée, la charge explose et ouvre un trou qui donne accès à la zone derrière le mur, permettant aux attaquants d'entrer facilement tout en retirant la sécurité que les défenseurs ont mise en place avec leurs renforcements. \r\n\r\nThermite doit se distancier lorsqu'il s'active, car la charge provoque une explosion significative qui peut être dangereuse si elle est à proximité. Cette capacité est particulièrement utile pour prendre le contrôle des zones critiques et pour forcer les défenseurs à repositionner leur stratégie.\r\n\r\nEquipement :\r\nEn plus de sa capacité spéciale, Thermite dispose généralement d’armes efficaces telles que le M1014 (fusil à pompe) ou le 556XI (fusil d'assaut) et des gadgets comme les grenades ou les drones, qui complètent son ensemble pour s’adapter à diverses situations de jeu.\r\n\r\nThermite est souvent considéré comme un personnage essentiel pour les équipes qui cherchent à briser les défenses adverses, particulièrement sur les cartes qui comportent de nombreux murs renforcés." });
            Enfants.Add(new Enfant() { Id = 11, IdParent = 3, Nom = "Ash", Âge = "33 ans", ImageEnfant = "Images/ash.jpg", Camp = "Attaquant", Clan = "FBI SWAT", NiveauDeDifficultés = 2, Abilité = "Breachin Round", Fonction = "Breacher", Description = "Ash est un opérateur Attaquant de la faction des États-Unis. Elle est connue pour sa rapidité et sa capacité à détruire des murs et des barricades à distance grâce à son équipement. \r\n\r\n Description de Ash :\r\nAsh est dépeinte comme une opératrice agile et efficace, faisant partie du groupe des Forces spéciales américaines. Elle est souvent vue comme une tireuse d'élite et utilise ses compétences pour infiltrer et exposer ses ennemis. Son style de jeu se concentre sur la mobilité et l’attaque rapide.\r\n\r\nCapacité :\r\nL'ability d'Ash est son LWS (Lightweight Grenade Launcher), qui lui permet de tirer des projectiles explosifs capables de détruire des murs, des barricades et des objets destructibles à distance. Cette fonctionnalité lui permet non seulement de créer des ouvertures dans les défenses ennemies sans se mettre en danger, mais aussi d’infliger des dégâts aux ennemis qui se trouvent à proximité de l'impact. Ash est donc très efficace pour prendre l'initiative et désorienter les défenseurs, facilitant ainsi l'avancée de son équipe.\r\n\r\nEn résumé, Ash est un personnage rapide et agile qui utilise son lance-grenades pour détruire des obstacles et créer des opportunités d'attaque sur le champ de bataille." });
            Enfants.Add(new Enfant() { Id = 12, IdParent = 3, Nom = "Hibana", Âge = "34 ans", ImageEnfant = "Images/hibana.jpg", Camp = "Attaquant", Clan = "CTUs", NiveauDeDifficultés = 1, Abilité = "X-KAIROS", Fonction = "Breacher", Description = "Hibana est un opérateur du groupe d'intervention japonais, le SAT (Special Assault Team). Elle est spécialisée dans la destruction de murs renforcés et est connue pour son équipement unique.\r\n\r\nDescription de Hibana :\r\nHibana est présentée comme une combattante stratégique et technique. Dans le lore du jeu, elle a été formée pour être une spécialiste en démolition. Elle est souvent décrite comme déterminée, astucieuse et méticuleuse dans son approche des situations de combat.\r\n\r\n Capacités :\r\nL'arme principale de Hibana est le \"X-KAIROS\", un appareil qui lui permet de tirer des balles de thermite sur les surfaces renforcées. Voici comment fonctionne son équipement :\r\n\r\n- X-KAIROS : Hibana utilise cette arme pour tirer des explosifs qui créent de petites ouvertures dans les murs renforcés ou les barricades. Contrairement à Thermite, qui crée une grande ouverture instantanée, Hibana peut tirer plusieurs billes qui, une fois fixées à la surface, explosent et ouvrent plusieurs petits trous, permettant ainsi aux joueurs de passer à travers ou d'observer l'intérieur de la pièce.\r\n\r\n### Atouts de son utilisation :\r\n- Polyvalence : Elle peut ouvrir des points d'accès pour son équipe, ce qui permet de prendre un avantage stratégique.\r\n- Sécuritée : Grâce à sa capacité à ouvrir des barricades à distance, Hibana peut rester à couvert tout en exerçant une pression sur les défenseurs.\r\n\r\nHibana est souvent choisie dans les compositions d'équipe pour ses compétences uniques, ce qui en fait un atout précieux lors des attaques." });

            Favori.Add(new Favoris() { IdFavoris = 1, NomFavoris = "Jager", FonctionFavoris = "Anti-Gadget", NiveauDeDifficultésFavoris = 2, ImageFavoris = "/Images/Jager.jfif"});
            Favori.Add(new Favoris() { IdFavoris = 2, NomFavoris = "Ash", FonctionFavoris = "Breacher", NiveauDeDifficultésFavoris = 2, ImageFavoris = "/Images/ash.jpg"});
            Favori.Add(new Favoris() { IdFavoris = 3, NomFavoris = "Valkyrie", FonctionFavoris = "Support", NiveauDeDifficultésFavoris = 2, ImageFavoris = "/Images/téléchargement.jfif" });
            //Lier objets Enfant aux Parent
            foreach (var p in Parents)
            {
                p.Enfants = new List<Enfant>();
                var enfants = Enfants.Where(e => e.IdParent == p.Id).ToList();
                p.Enfants.AddRange(enfants);
               
            }

            //Lier objets Parents aux Enfants
            foreach (var e in Enfants)
            {
                e.Parent = Parents.Where(q => q.Id == e.IdParent)
                    .Single();
              
            }
            //Lier objets Enfant aux Favoris
            foreach (var p in Favori)
            {
                p.Enfants = new List<Enfant>();
                var enfant = Enfants.Where(a => a.Id == p.IdFavoris);
                p.Enfants.AddRange(enfant);
            }
        }
    }
}
